module TopModule(
   input   clk,
   input   rst_n,

   output  reg [3:0] gray_out
);
//Gray code to binary conversion
reg  [3:0] bin_out;
wire [3:0] gray_wire;

always @(posedge clk or negedge rst_n)begin
   if(rst_n == 1'b0) begin
      bin_out <= 4'b0;
   end
   else begin
      bin_out[3] <= gray_wire[3];
      bin_out[2] <= gray_wire[2]^gray_wire[3];
      bin_out[1] <= gray_wire[1]^gray_wire[2]^gray_wire[3];
      bin_out[0] <= gray_wire[0]^gray_wire[1]^gray_wire[2]^gray_wire[3];
   end 
end
//Binary increment
reg [3:0] bin_add_wire;
always @(posedge clk or negedge rst_n)begin
   if(rst_n == 1'b0) begin
      bin_add_wire <= 4'b0;
   end
   else begin
      bin_add_wire <= (cycle_count == 1) ? (bin_out + 1'b1) : bin_out;
   end
end
//Cycle counter for 2-cycle increment
reg cycle_count;
always @(posedge clk or negedge rst_n)begin
   if(rst_n == 1'b0) begin
      cycle_count <= 1'b0;
   end
   else begin
      cycle_count <= ~cycle_count;
   end
end
//Binary to gray code conversion
assign gray_wire = (bin_add_wire >> 1) ^ bin_add_wire;

always @(posedge clk or negedge rst_n)begin
   if(rst_n == 1'b0) begin
      gray_out <= 4'b0;
   end
   else begin
      gray_out <= gray_wire;
   end
end
endmodule

